/* From Uiverse.io by Vikikos - Tags: card */
.__UIV_SCOPE__ .card {
 width: 190px;
 height: 254px;
 box-shadow: 0 10px 10px rgba(0, 0, 0, 0.212);
 background: #fff;
 display: flex;
 border-radius: 20px;
 justify-content: center;
 position: relative;
 transition: all .4s;
}

.__UIV_SCOPE__ .card::before {
 content: '---content---';
 letter-spacing: 0.2em;
 position: absolute;
 bottom: 8px;
 left: 20px;
 color: rgb(51, 51, 51);
 font-size: 0.8em;
 font-weight: 700;
}

.__UIV_SCOPE__ .card div {
 width: 100%;
 height: 100%;
 border-radius: 20px;
 box-shadow: 0 0 10px rgba(0, 0, 0, 0.212);
 cursor: pointer;
 z-index: 10;
 transition: all .4s;
 background-color: #fff;
}

.__UIV_SCOPE__ .card:hover div {
 transform: translateY(-30px);
}
